use crate::{cq27 as b,model::*,unit_support::*};
fn top(g:&mut Game){for _ in 0..60{if g.pending.is_some()||g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!()}
fn prepare(g:&mut Game,id:&str){g.turn+=1;g.begin_window(Window::Prepare);g.drive().unwrap();choose(g,vec![id.into()]);top(g);}
#[test]fn cq27_preparation_bottoms_one_own_character_and_generates_slow_walker(){assert_current_serial_catalog();let mut g=game();let id=field(&mut g,b::ID,0);let c=g.make_card("JC125",0);g.players[0].graveyard.push(c);prepare(&mut g,&id);restore(&mut g);let p=g.pending.as_ref().unwrap();assert_eq!(p.choice.kind,"cq27-bottom");let id=p.choice.options[0].id.clone();choose(&mut g,vec![id]);assert_eq!(g.players[0].deck.last().unwrap().definition,"JC125");assert!(g.regions[0].cards.iter().any(|c|c.definition=="TK001"&&c.exhausted));restore(&mut g);}
#[test]fn cq27_grave_return_pays_three_real_characters_then_randomizes_once(){let mut g=game();let c=g.make_card(b::ID,0);let id=c.id.clone();g.players[0].graveyard.push(c);let ids=(0..3).map(|_|field(&mut g,"JC125",0)).collect();let rng=g.random;act(&mut g,0,Action{card_id:Some(id),ability_id:Some(b::GRAVE.into()),cost_selected:Some(ids),..Action::new("activate")});assert_eq!(g.random,rng);restore(&mut g);let mut expected=g.clone();let r=expected.chaos_region().unwrap();top(&mut g);assert_eq!(g.random,expected.random);assert!(g.regions[r].cards.iter().any(|c|c.definition==b::ID));restore(&mut g);}
fn grave_setup()->(Game,String,Vec<String>){let mut g=game();let c=g.make_card(b::ID,0);let id=c.id.clone();g.players[0].graveyard.push(c);let ids=(0..3).map(|_|field(&mut g,"JC125",0)).collect();(g,id,ids)}
fn grave_action(id:&str,ids:Vec<String>)->Action{Action{card_id:Some(id.into()),ability_id:Some(b::GRAVE.into()),cost_selected:Some(ids),..Action::new("activate")}}
fn bad(g:&Game,x:&Game){assert!(Game::from_persisted(&serde_json::to_string(x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=x.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn cq27_duplicate_hidden_foreign_and_incomplete_sacrifices_reject_without_payment(){let(mut g,id,ids)=grave_setup();for v in [vec![ids[0].clone();3],ids[..2].to_vec()]{reject(&mut g,0,grave_action(&id,v));}let ally=field(&mut g,"JC125",1);let enemy=field(&mut g,"JC125",2);let hidden=field(&mut g,"JC125",0);g.regions[0].cards.iter_mut().find(|c|c.id==hidden).unwrap().face_down=true;for other in [ally,enemy,hidden]{reject(&mut g,0,grave_action(&id,vec![ids[0].clone(),ids[1].clone(),other]));}assert_eq!(g.players[0].graveyard.len(),1);assert!(ids.iter().all(|id|g.board(id).is_some()));}
#[test]fn cq27_source_removed_during_response_cancels_without_rng_or_refund(){let(mut g,id,ids)=grave_setup();act(&mut g,0,grave_action(&id,ids.clone()));assert!(ids.iter().all(|id|g.board(id).is_none()));g.players[0].graveyard.retain(|c|c.id!=id);let replacement=g.make_card(b::ID,0);g.players[0].graveyard.push(replacement);let rng=g.random;top(&mut g);assert_eq!(rng,g.random);assert!(!g.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition==b::ID));restore(&mut g);}
#[test]fn cq27_generated_cost_disappears_and_physical_cost_goes_to_grave(){let(mut g,id,mut ids)=grave_setup();g.regions[0].cards.retain(|c|c.id!=ids[2]);let c=g.make_generated(crate::generated::GeneratedKind::Walker,0).unwrap();let birth=c.generated.clone();ids[2]=c.id.clone();g.regions[0].cards.push(c);act(&mut g,0,grave_action(&id,ids));assert!(!g.batch3_physical_cards().any(|c|c.generated==birth));assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition=="JC125").count(),2);top(&mut g);restore(&mut g);}
#[test]fn cq27_prepare_empty_grave_generates_and_only_own_characters_are_selectable(){let mut g=game();let id=field(&mut g,b::ID,0);let c=g.make_card("JC125",1);g.players[1].graveyard.push(c);let c=g.make_card("BQ088",0);g.players[0].graveyard.push(c);prepare(&mut g,&id);assert!(!g.pending.as_ref().is_some_and(|p|p.choice.kind=="cq27-bottom"));assert_eq!(g.regions[0].cards.iter().filter(|c|c.definition=="TK001").count(),1);restore(&mut g);}
#[test]fn cq27_pending_is_mandatory_exact_and_rejects_duplicate_commands(){let mut g=game();let id=field(&mut g,b::ID,0);let c=g.make_card("JC125",0);g.players[0].graveyard.push(c);prepare(&mut g,&id);let p=g.pending.as_ref().unwrap();let a=Action{choice_id:Some(p.choice.id.clone()),selected:Some(vec![p.choice.options[0].id.clone()]),..Action::new("choose")};reject(&mut g,0,Action{selected:Some(vec![]),..a.clone()});reject(&mut g,1,a.clone());for n in 0..3{let mut x=g.clone();let p=x.pending.as_mut().unwrap();match n{0=>p.choice.min=Some(0),1=>p.choice.options.clear(),_=>p.seat=1}bad(&g,&x);}act(&mut g,0,a.clone());reject(&mut g,0,a);restore(&mut g);}
#[test]fn cq27_paid_return_receipt_corruption_rejected_by_game_and_room(){let(mut g,id,ids)=grave_setup();act(&mut g,0,grave_action(&id,ids));for n in 0..4{let mut x=g.clone();let f=x.stack.last_mut().unwrap().frame.as_mut().unwrap();match n{0=>f.steps.clear(),1=>f.already_paid.clear(),2=>{let PaidCost::CQ27Sacrificed(v)=&mut f.already_paid[0]else{panic!()};v[1]=v[0].clone();},_=>f.source.card.definition="JC125".into()}bad(&g,&x);}restore(&mut g);}
#[test]fn cq27_normal_deploy_chaos_and_faceup_movement_prohibition(){let mut g=game();fund(&mut g,0,"BQ092",5);let id=held(&mut g,b::ID,0);let a=Action{card_id:Some(id.clone()),..Action::new("deploy")};reject(&mut g,0,Action{region:Some(0),..a.clone()});act(&mut g,0,a);for n in 0..2{let mut x=g.clone();let i=x.stack.last_mut().unwrap();if n==0{i.frame=None;}else{i.frame.as_mut().unwrap().source.card.definition="JC125".into();}bad(&g,&x);}let mut expected=g.clone();let r=expected.chaos_region().unwrap();top(&mut g);assert_eq!(g.random,expected.random);let id=g.regions[r].cards.iter().find(|c|c.definition==b::ID).unwrap().id.clone();let target=(r+1)%g.regions.len();g.move_on_board_instance(&id,target);assert_eq!(g.board(&id).unwrap().0,r);g.hide_in_place(&id);let id=g.regions[r].cards.iter().find(|c|c.definition==b::ID).unwrap().id.clone();g.move_on_board_instance(&id,target);assert_eq!(g.board(&id).unwrap().0,target);restore(&mut g);}
#[test]fn cq27_nonasset_requires_exposure_and_conceal_remains_legal(){let mut g=game();fund(&mut g,0,"BQ092",1);let id=held(&mut g,b::ID,0);let c=g.players[0].hand.iter().find(|c|c.id==id).unwrap().clone();g.players[0].society_zone.exposure=0;assert!(!g.current_non_asset(&c,0));g.players[0].society_zone.exposure=1;assert!(g.current_non_asset(&c,0));reject(&mut g,0,Action{card_id:Some(id.clone()),..Action::new("asset")});act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("conceal")});top(&mut g);assert!(g.regions[0].cards.iter().any(|c|c.definition==b::ID&&c.face_down));restore(&mut g);}
use crate::{catalog,abi112_review_play_tests::Trace};
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert!(!d.changed&&d.journal.is_empty());assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn construct(seed:u64)->Game{use crate::deck;let mut d=deck::preset("watchers").unwrap();d.id="cq27-natural".into();d.society_id=None;d.core_card_id=None;d.cards=[(b::ID,3),("BQ088",3),("BQ092",3),("JC125",41)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if [b::ID,"BQ088"].contains(&c.id.as_str()){c.supported=true;}}let d=deck::validate_with_cards(d,&cards).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("cq27".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
fn initial_choice(g:&Game)->Vec<String>{let p=g.pending.as_ref().unwrap();let mut opts=p.choice.options.iter().collect::<Vec<_>>();opts.sort_by_key(|o|g.players[p.seat].hand.iter().any(|c|c.id==o.id&&[b::ID,"BQ088","BQ092"].contains(&c.definition.as_str())));opts.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()}
fn natural()->serde_json::Value{let seed=(1..10000).find(|seed|{let mut g=construct(*seed);for _ in 0..40{if g.pending.is_some(){let ids=initial_choice(&g);choose(&mut g,ids);}else if g.legal_actions(0).iter().any(|a|a.action.kind=="asset"){break;}else{let Some(s)=(0..4).find(|s|g.legal_actions(*s).iter().any(|a|a.action.kind=="pass"))else{return false;};g.apply(s,Action::new("pass")).unwrap();}}g.players[0].hand.iter().any(|c|c.definition=="BQ088")&&g.players[0].hand.iter().any(|c|c.definition=="BQ092")&&g.players[0].hand.iter().filter(|c|c.definition=="JC125").count()>=2&&g.players[0].deck.first().is_some_and(|c|c.definition==b::ID)}).expect("deterministic legal construction seed");let g=construct(seed);let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"cq27-natural-fifty-mill-sacrifice-return-prepare".into(),851);let mut returned=false;let mut prepared=false;for _ in 0..1400{if let Some(p)=t.room.game.pending.clone(){if matches!(&p.resolution,ChoiceResolution::Forecast{..}|ChoiceResolution::Frame{choice:FrameChoice::Forecast{..},..}){let top=p.choice.options.iter().map(|o|o.id.clone()).collect();t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(top),bottom:Some(vec![]),..Action::new("choose")});continue;}let ids=if p.choice.kind=="cq27-bottom"{prepared=true;vec![p.choice.options[0].id.clone()]}else if p.choice.options.iter().any(|o|t.room.game.board(&o.id).is_some_and(|(_,c)|c.definition==b::ID)){vec![p.choice.options.iter().find(|o|t.room.game.board(&o.id).is_some_and(|(_,c)|c.definition==b::ID)).unwrap().id.clone()]}else{initial_choice(&t.room.game)};t.choose(ids);continue;}if prepared&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let a=if returned{None}else if let Some(a)=legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::GRAVE)){returned=true;Some(a)}else if g.players[0].graveyard.iter().any(|c|c.definition==b::ID){legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="JC125")))}else if g.players[0].assets.is_empty(){legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="BQ092")))}else{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::bq088::KEY)&&a.action.option.as_deref()==Some("generate"))};if let Some(a)=a{t.action(0,a.action.clone());}else{t.pass();}}assert!(returned&&prepared);assert_eq!(t.room.game.regions.iter().flat_map(|r|&r.cards).filter(|c|c.definition==b::ID).count(),1);assert_eq!(t.room.game.regions.iter().flat_map(|r|&r.cards).filter(|c|c.definition=="TK001").count(),1);let mut v=t.value();v["construction"]=serde_json::json!({"seed":seed,"deck":deck,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)}
#[test]fn cq27_native_natural_export(){let cases=vec![natural(),prepared_entry(false),prepared_entry(true)];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/cq27.rs",include_bytes!("cq27.rs").as_slice()),("rust-game/src/cq27_tests.rs",include_bytes!("cq27_tests.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("CQ27_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

fn prepared_entry(reveal:bool)->serde_json::Value{let mut g=game();fund(&mut g,0,"BQ092",5);let id=if reveal{let id=field(&mut g,b::ID,0);g.regions[0].cards.iter_mut().find(|c|c.id==id).unwrap().face_down=true;id}else{held(&mut g,b::ID,0)};let mut t=Trace::new_preserving_rng(g,format!("cq27-prepared-{}",if reveal{"reveal"}else{"deploy"}),852+usize::from(reveal));t.action(0,Action{card_id:Some(id),..Action::new(if reveal{"reveal"}else{"deploy"})});for _ in 0..30{if t.room.game.stack.is_empty(){break;}t.pass();}assert_eq!(t.room.game.regions.iter().flat_map(|r|&r.cards).filter(|c|c.definition==b::ID&&!c.face_down).count(),1);duplicate(t.value())}
